(6806132, 1023564, 62249, '<td valign="top">Good colors and I like the overall composition. The foreground pottery vessel is distracting.</td>', 'Good colors and I like the overall composition. The foreground pottery vessel is distracting.', '2012-07-02 02:01:16.000000', NULL, 1),
(6806134, 1023838, 62249, '<td valign="top">Seems more like an outtake from the motion challenge rather than something shot for the Zen challenge. Nevertheless, it''s a very interesting image that I like a lot. It''s borderline eerie and makes viewers want to know the back story.</td>', 'Seems more like an outtake from the motion challenge rather than something shot for the Zen challenge. Nevertheless, it''s a very interesting image that I like a lot. It''s borderline eerie and makes viewers want to know the back story.', '2012-07-02 02:03:34.000000', NULL, 1),
(6806146, 1023884, 62249, '<td valign="top">The border detracts from an otherwise strong image. Dramatic colors and silhouette are effective.</td>', 'The border detracts from an otherwise strong image. Dramatic colors and silhouette are effective.', '2012-07-02 02:11:57.000000', NULL, 1),
